responses = {    "hello": "Hi there! 👋 How can I help you today?",    "hi": "Hello! 😊 Nice to meet you!",    "hey": "Hey! What can I do for you?",    "how are you": "I'm just a bot, but I'm doing great! 😄 How about you?",    "what is a chatbot": "A chatbot is a computer program designed to simulate conversation with humans! 🤖",    "how do chatbots work": "Chatbots work by matching user input to predefined responses using keywords or AI models.",    "types of chatbots": "There are mainly 3 types:\n  1. Rule-based chatbots (like me!)\n  2. Retrieval-based chatbots\n  3. Generative AI chatbots (like ChatGPT)",    "what can you do": "I can answer basic questions using predefined responses. I cannot learn or improvise!",    "who made you": "I was created as a simple Python chatbot demo! 🛠️",    "what is python": "Python is a popular programming language known for its simplicity and versatility.",    "help": "You can ask me about chatbots, Python, or just say hello! Type 'quit' to exit.",    "thank you": "You're welcome! 😊",    "thanks": "Happy to help! 😊",    "bye": "Goodbye! 👋 Have a great day!",    "goodbye": "See you later! 👋",}def get_response(user_input):    user_input = user_input.lower().strip()    for keyword, reply in responses.items():        if keyword in user_input:            return reply    return "🤔 Sorry, I don't understand that. Type 'help' to see what I can do!"def start_chat():    print("=" * 50)    print("🤖 Welcome to StudyBot!")    print("  A Simple Chatbot with Predefined Responses")    print("=" * 50)    print("  Type 'quit' or 'exit' to stop the chat.\n")    while True:        user_input = input("You: ").strip()        if not user_input:            continue        if user_input.lower() in ("quit", "exit"):            print("Bot: Goodbye! 👋 Thanks for chatting!")            break        reply = get_response(user_input)        print(f"Bot: {reply}\n")if __name__ == "__main__":    start_chat()